Subroutine Suspendable Medir(sensor As Channel<Integer>)
  For medida <- 1 To 5 Do
    Define temperatura As Integer;
    Read temperatura;
    Define aceptado As Boolean <- Await sensor.send(temperatura);
    If Not aceptado Then
      Write "El sensor se desconectó";
    EndIf
  EndFor
  sensor.close();
EndSubroutine

Subroutine Suspendable Promediar(sensor As Channel<Integer>)
  Define suma As Integer <- 0;
  Define medidas As Integer <- 0;
  Repeat
    Switch Await sensor.receive() Do
      Some(temperatura):
        suma <- suma + temperatura;
        medidas <- medidas + 1;
      None: Break;
    EndSwitch
  Until False
  Write suma / medidas;
EndSubroutine

Algorithm Sensor
  Define sensor As Channel<Integer> <- channel(2);
  Tasks
    Spawn Medir(sensor);
    Spawn Promediar(sensor);
  EndTasks
EndAlgorithm
